{
  "summary": "I need the story premise to define qualities that measure the actual dramatic state; please answer these or say 'you decide' and I'll use flexible defaults.",
  "questions": [
    {
      "id": "premise_genre",
      "text": "What is the core premise and genre of the story?",
      "why": "Quality keys and rubrics need concrete nouns (who, what, where) to be extractable from prose.",
      "options": [
        "Survival/escape",
        "Mystery/investigation",
        "Romance/relationship",
        "Power/ambition",
        "Other (describe)"
      ]
    },
    {
      "id": "protagonist_goal",
      "text": "Who is the protagonist, and what do they want most at the start?",
      "why": "Resolve, progress, and goal-clarity qualities must name the protagonist and their objective.",
      "options": [
        "You decide"
      ]
    },
    {
      "id": "central_relationship",
      "text": "Which relationship or opposition should qualities track most closely?",
      "why": "Trust, pressure, and loyalty qualities need a specific person or faction to read from the prose.",
      "options": [
        "A specific ally",
        "A specific rival",
        "An internal flaw/doubt",
        "A faction or force",
        "None yet — use generic dramatic states"
      ]
    }
  ]
}

